#include "script_workspace.h"
#include "event_tools.h"
#include "game_script.h"
#include <QtWidgets>
namespace cf {
ScriptWorkspace::ScriptWorkspace(QWidget *parent):QWidget(parent){auto *root=new QVBoxLayout(this);auto *tabs=new QTabWidget;root->addWidget(tabs);auto *editor=new QWidget;tabs->addTab(editor,"Event scripts");auto *row=new QHBoxLayout(editor);auto *left=new QVBoxLayout;types=new QComboBox;types->addItems({"Scenes","Areas","Objects","NPCs","Dialogues","Items","Scripts","Timers"});left->addWidget(new QLabel("Element type"));left->addWidget(types);elements=new QListWidget;elements->setMinimumWidth(210);left->addWidget(elements,1);deleteScript=new QPushButton("Delete script…");deleteScript->setToolTip("Delete the selected reusable script (Element type: Scripts).");left->addWidget(deleteScript);row->addLayout(left,1);
connect(deleteScript,&QPushButton::clicked,this,[this]{
        auto *item=elements->currentItem();if(!item||types->currentText()!="Scripts")return;
        const QString id=item->data(Qt::UserRole).toString();int index=-1;for(int i=0;i<project.scripts.size();++i)if(project.scripts[i].id==id)index=i;if(index<0)return;
        const QString name=project.scripts[index].name;Project trial=project;trial.scripts.removeAt(index);const int mentions=trial.idMentions(id);
        QString text="Delete the script \""+name+"\" ["+id+"]?\n\nEdit \u2192 Undo project change brings it back.";
        if(mentions>0)text+=QString("\n\nAlso:\n%1 place(s) in other scripts or events still mention \"%2\" (for example call %2) and will report an unknown script until you change them.").arg(mentions).arg(id);
        if(QMessageBox::question(this,"Delete script",text,QMessageBox::Yes|QMessageBox::No,QMessageBox::No)!=QMessageBox::Yes)return;
        project=trial;if(onEdit)onEdit(trial);setProject(trial);
    });auto *middle=new QVBoxLayout;events=new QComboBox;middle->addWidget(events);source=new QPlainTextEdit;source->setFont(QFontDatabase::systemFont(QFontDatabase::FixedFont));source->setPlaceholderText("# Runs only when this event fires\n# Use + Event or double-click a reference");middle->addWidget(eventTools(source,[this]{return project;}),1);status=new QLabel;status->setWordWrap(true);middle->addWidget(status);row->addLayout(middle,3);auto *right=new QVBoxLayout;right->addWidget(new QLabel("Insert reference · double-click"));referenceTypes=new QComboBox;referenceTypes->addItems({"Scenes","Variables","Dialogues","Scripts","Storage","Items","Timers","Areas","Objects","NPCs"});right->addWidget(referenceTypes);references=new QListWidget;references->setMinimumWidth(220);right->addWidget(references,1);auto *help=new QLabel("Scene / dialogue / script references insert a complete command. Variables and items insert an ID at the cursor. Object and NPC entries call their interaction event. IDs stay stable when names change.");help->setWordWrap(true);right->addWidget(help);row->addLayout(right,1);json=new QPlainTextEdit;json->setReadOnly(true);json->setFont(QFontDatabase::systemFont(QFontDatabase::FixedFont));tabs->addTab(json,"Live project JSON (read-only)");connect(types,&QComboBox::currentIndexChanged,this,[this]{if(!filling)list();});connect(elements,&QListWidget::currentRowChanged,this,[this]{if(!filling)select();});connect(events,&QComboBox::currentIndexChanged,this,[this]{if(filling)return;int b=events->currentData().toInt();filling=true;source->setPlainText(b>=0&&b<bindings.size()?bindings[b].read(project):QString());source->setEnabled(b>=0&&b<bindings.size());filling=false;});connect(referenceTypes,&QComboBox::currentIndexChanged,this,[this]{refs();});connect(references,&QListWidget::itemDoubleClicked,this,[this](QListWidgetItem *item){auto text=item->data(Qt::UserRole).toString();auto cursor=source->textCursor();if(text.contains('\n')&&cursor.position()>0&&source->toPlainText()[cursor.position()-1]!='\n')text.prepend('\n');cursor.insertText(text);source->setTextCursor(cursor);source->setFocus();});connect(source,&QPlainTextEdit::textChanged,this,[this]{if(filling)return;int b=events->currentData().toInt();if(b<0||b>=bindings.size())return;auto p=project;bindings[b].write(p,source->toPlainText());project=p;QVector<CFInstruction> code;QString error;status->setText(GameCompiler(project).program(source->toPlainText(),code,error)?QString("Valid · %1 instructions · saved in the project; Undo applies").arg(code.size()):error);editing=true;if(onEdit)onEdit(p);editing=false;json->setPlainText(QJsonDocument(project.toJson()).toJson(QJsonDocument::Indented));});}
void ScriptWorkspace::populateBindings(){bindings.clear();auto add=[&](QString type,QString name,QString id,QString event,auto read,auto write){bindings<<Binding{type,name,id,event,read,write};};for(int i=0;i<project.scenes.size();++i){auto s=project.scenes[i];add("Scenes",s.name,s.id,"onSceneEnter",[i](const Project&p){return p.scenes[i].onSceneEnter;},[i](Project&p,QString s){p.scenes[i].onSceneEnter=s;});add("Scenes",s.name,s.id,"onBack",[i](const Project&p){return p.scenes[i].onBack;},[i](Project&p,QString s){p.scenes[i].onBack=s;});for(int e=0;e<s.elements.size();++e)if(s.elements[e].type=="button")add("Scenes",s.name,s.id,"Button: "+s.elements[e].name,[i,e](const Project&p){return p.scenes[i].elements[e].actions;},[i,e](Project&p,QString s){p.scenes[i].elements[e].actions=s;});}
for(int w=0;w<project.allAreas().size();++w){auto area=project.allAreas()[w];auto world=[w](Project &p)->World&{return w?p.areas[w-1]:p.world;};add("Areas",area.name,area.id,"onAreaEnter",[w](const Project&p){return p.allAreas()[w].onStart;},[world](Project&p,QString s){world(p).onStart=s;});for(int e=0;e<area.terrainEvents.size();++e)add("Areas",area.name,area.id,QString("Terrain %1").arg(e),[w,e](const Project&p){return p.allAreas()[w].terrainEvents[e].script;},[world,e](Project&p,QString s){world(p).terrainEvents[e].script=s;});for(int o=0;o<area.objects.size();++o)for(int ev=0;ev<2;++ev)add("Objects",area.name+" / "+area.objects[o].name,area.id+"/"+area.objects[o].id,ev?"onHit":"onInteract",[w,o,ev](const Project&p){auto o2=p.allAreas()[w].objects[o];return ev?o2.onHit:o2.onInteract;},[world,o,ev](Project&p,QString s){if(ev)world(p).objects[o].onHit=s;else world(p).objects[o].onInteract=s;});for(int a=0;a<area.actors.size();++a)for(int ev=0;ev<3;++ev)add("NPCs",area.name+" / "+area.actors[a].name,area.id+"/"+area.actors[a].id,QStringList{"onInteract","onHit","onDefeat"}[ev],[w,a,ev](const Project&p){auto x=p.allAreas()[w].actors[a];return ev==0?x.onInteract:ev==1?x.onHit:x.onDefeat;},[world,a,ev](Project&p,QString s){auto &x=world(p).actors[a];if(ev==0)x.onInteract=s;else if(ev==1)x.onHit=s;else x.onDefeat=s;});}
for(int i=0;i<project.npcs.size();++i)for(int ev=0;ev<3;++ev)add("NPCs","Library / "+project.npcs[i].name,"library/"+project.npcs[i].id,QStringList{"onInteract","onHit","onDefeat"}[ev],[i,ev](const Project&p){auto a=p.npcs[i].actor;return ev==0?a.onInteract:ev==1?a.onHit:a.onDefeat;},[i,ev](Project&p,QString s){auto &a=p.npcs[i].actor;if(ev==0)a.onInteract=s;else if(ev==1)a.onHit=s;else a.onDefeat=s;});
for(int i=0;i<project.prompts.size();++i){auto n=project.prompts[i];add("Dialogues",n.title,n.id,"onEnter",[i](const Project&p){return p.prompts[i].onEnter;},[i](Project&p,QString s){p.prompts[i].onEnter=s;});for(int c=0;c<n.choices.size();++c)add("Dialogues",n.title,n.id,"Choice: "+n.choices[c].text,[i,c](const Project&p){return p.prompts[i].choices[c].actions;},[i,c](Project&p,QString s){p.prompts[i].choices[c].actions=s;});}
for(int i=0;i<project.items.size();++i)add("Items",project.items[i].name,project.items[i].id,"onUse",[i](const Project&p){return p.items[i].useScript;},[i](Project&p,QString s){p.items[i].useScript=s;});for(int i=0;i<project.scripts.size();++i)add("Scripts",project.scripts[i].name,project.scripts[i].id,"Source",[i](const Project&p){return p.scripts[i].source;},[i](Project&p,QString s){p.scripts[i].source=s;});for(int i=0;i<project.timers.size();++i)add("Timers",project.timers[i].name,project.timers[i].id,"onTimeout",[i](const Project&p){return p.timers[i].source;},[i](Project&p,QString s){p.timers[i].source=s;});}
void ScriptWorkspace::setProject(const Project &p){project=p;if(editing)return;QString id=elements->currentItem()?elements->currentItem()->data(Qt::UserRole).toString():QString(),event=events->currentText();filling=true;populateBindings();filling=false;list();for(int i=0;i<elements->count();++i)if(elements->item(i)->data(Qt::UserRole).toString()==id)elements->setCurrentRow(i);int e=events->findText(event);if(e>=0)events->setCurrentIndex(e);refs();json->setPlainText(QJsonDocument(p.toJson()).toJson(QJsonDocument::Indented));}
void ScriptWorkspace::list(){filling=true;elements->clear();QSet<QString> seen;for(auto &b:bindings)if(b.type==types->currentText()&&!seen.contains(b.id)){seen.insert(b.id);auto *item=new QListWidgetItem(b.name+"\n["+b.id+"]",elements);item->setData(Qt::UserRole,b.id);}elements->setCurrentRow(0);filling=false;select();}
void ScriptWorkspace::select(){if(deleteScript){deleteScript->setVisible(types->currentText()=="Scripts");deleteScript->setEnabled(elements->currentItem()!=nullptr);}filling=true;events->clear();QString id=elements->currentItem()?elements->currentItem()->data(Qt::UserRole).toString():QString();for(int i=0;i<bindings.size();++i)if(bindings[i].type==types->currentText()&&bindings[i].id==id)events->addItem(bindings[i].event,i);int b=events->currentData().isValid()?events->currentData().toInt():-1;source->setEnabled(b>=0);source->setPlainText(b>=0?bindings[b].read(project):QString());status->setText(b>=0?"Edits update the project immediately. Build & Play tests the real ROM.":"Create an element in Project & game data first.");filling=false;}
void ScriptWorkspace::refs(){references->clear();auto add=[&](QString name,QString id,QString insertion){auto *item=new QListWidgetItem(name+"\n["+id+"]",references);item->setData(Qt::UserRole,insertion);};auto type=referenceTypes->currentText();if(type=="Scenes")for(auto &s:project.scenes)add(s.name,s.id,"scene "+s.id+"\n");if(type=="Variables"){for(auto &v:project.variables)add(v.id,v.id,v.id);add("Read-only operation result","result","result");}if(type=="Dialogues")for(auto &p:project.prompts)add(p.title,p.id,"dialogue "+p.id+"\n");if(type=="Scripts")for(auto &s:project.scripts)add(s.name,s.id,"call "+s.id+"\n");if(type=="Storage")for(auto &s:project.storages)add(s.name,s.id,"open "+s.id+"\n");if(type=="Items")for(auto &i:project.items)add(i.name,i.id,i.id);if(type=="Timers")for(auto &t:project.timers)add(t.name,t.id,"timer start "+t.id+"\n");if(type=="Areas")for(auto &a:project.runtimeAreas())add(a.name,a.id,"area "+a.id+"\n");for(auto &a:project.allAreas()){if(type=="Objects")for(auto &o:a.objects)add(a.name+" / "+o.name,o.id,"object "+a.id+" "+o.id+" interact\n");if(type=="NPCs")for(auto &n:a.actors)add(a.name+" / "+n.name,n.id,"npc "+a.id+" "+n.id+" interact\n");}}
}
